36	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
37	
38	export interface ScenarioResult {
39	  results: StepResult[];
40	}
41	
42	const PROCESSING_FEE = 5;
43	
44	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	const BLOCK_SIZE = 3;
54	const BLOCK_BASE_PREMIUM = 60;
55	
56	const formsBlock = (items: Item[]): boolean =>
57	  items.length === BLOCK_SIZE && items.every((item) => item.type === items[0].type);
58	
59	const sumBasePremiums = (items: Item[]): number =>
60	  items.reduce((total, item) => total + BASE_PREMIUM_BY_ITEM_TYPE[item.type], 0);
61	
62	const quote = ({ items }: QuoteStep): StepResult => {
63	  const totalBasePremium = formsBlock(items) ? BLOCK_BASE_PREMIUM : sumBasePremiums(items);
64	
65	  return { premium: totalBasePremium + PROCESSING_FEE };
66	};
67	
68	export const runScenario = (scenario: Scenario): ScenarioResult => ({
69	  results: [quote(scenario.steps[0] as QuoteStep)],
70	});
